package main

import "fmt"

type User struct{ Name string }

func rename(u User)     { u.Name = "x" } // edits a copy
func renamePtr(u *User) { u.Name = "x" } // edits the caller's struct

func main() {
	u := User{Name: "Ann"}
	rename(u)
	fmt.Println(u.Name) // unchanged
	renamePtr(&u)
	fmt.Println(u.Name) // changed
	// Output: Ann
	// x
}

package main

import "fmt"

type User struct{ Name string }

type Admin struct {
	User      // embedded (no field name)
	Level int
}

func main() {
	a := Admin{User: User{Name: "Ann"}, Level: 5}
	fmt.Println(a.Name, a.Level) // a.Name promoted from User
	// Output: Ann 5
}

package main

import (
	"encoding/json"
	"fmt"
)

type Point struct {
	X int `json:"x"`
	Y int `json:"y"`
}

func main() {
	fmt.Println(Point{1, 2} == Point{1, 2}) // comparable
	b, _ := json.Marshal(Point{X: 1, Y: 2})
	fmt.Println(string(b)) // tags rename JSON keys
	// Output: true
	// {"x":1,"y":2}
}

