package main

import "fmt"

type User struct{ Name string }

func rename(u *User) { // take a pointer to the caller's struct
	u.Name = "Bob"    // Go auto-dereferences: (*u).Name = "Bob"
}

func main() {
	u := User{Name: "Ann"}
	rename(&u)          // pass the address
	fmt.Println(u.Name) // Bob
}

