type Rectangle struct {
	Width, Height int
}

func (r Rectangle) Area() int { // value receiver: read-only
	return r.Width * r.Height
}

func (r *Rectangle) Scale(factor int) { // pointer receiver: mutates
	r.Width *= factor
	r.Height *= factor
}

type Point struct {
	X, Y int
}

func CountUnique(points []Point) int {
	seen := make(map[Point]struct{}, len(points)) // struct key, set-style value
	for _, p := range points {
		seen[p] = struct{}{} // Point is comparable, so it works as a key
	}
	return len(seen) // number of distinct points
}
